builder: (_) => SortPagesPage(pages: List.from(_pages)),
),
).then((reordered) {
if (reordered != null && mounted) {
setState(() {
_pages.clear();
_pages.addAll(reordered);
_currentIndex = 0;
_pageController.jumpToPage(0);
});
}
});
}
